def remove(self, name, qty):
    """Remove qty (a positive int) of item name from stock."""
    if name not in self._stock:
        raise KeyError(name)
    if isinstance(qty, bool) or not isinstance(qty, int) or qty <= 0:
        raise ValueError("qty must be a positive integer")
    if qty > self._stock[name]:
        raise ValueError("not enough stock")
    self._stock[name] -= qty
    if self._stock[name] == 0:
        del self._stock[name]

def total(self):
    """Total number of units in stock."""
    return sum(self._stock.values())

